import{c as a,Q as r,j as o,m as t}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Memory Beyond Recall: A Dual-Process Cognitive Memory System for Self-Evolving LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.09483","title":"Memory Beyond Recall: A Dual-Process Cognitive Memory System for Self-Evolving LLM Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.09483,"authors":["Tianxiang Fei","Mingyang Song","Mao Zheng","Xiang Yu"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2606.09483v1","pdf_path":"pdfs/2606.09483.pdf","published_date":"2026-06-08T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-08-memory-beyond-recall-dual-process-cognitive-memory-2606-09483.md","filePath":"research/papers/2026-06-08-memory-beyond-recall-dual-process-cognitive-memory-2606-09483.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-06-08-memory-beyond-recall-dual-process-cognitive-memory-2606-09483.md"};function n(i,e,l,c,m,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="memory-beyond-recall-a-dual-process-cognitive-memory-system-for-self-evolving-llm-agents" tabindex="-1">Memory Beyond Recall: A Dual-Process Cognitive Memory System for Self-Evolving LLM Agents <a class="header-anchor" href="#memory-beyond-recall-a-dual-process-cognitive-memory-system-for-self-evolving-llm-agents" aria-label="Permalink to &quot;Memory Beyond Recall: A Dual-Process Cognitive Memory System for Self-Evolving LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Tianxiang Fei, Mingyang Song, Mao Zheng, Xiang Yu <strong>Published</strong>: June 08, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.09483" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.09483</a> · <a href="https://arxiv.org/html/2606.09483v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.09483 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.09483" target="_blank" rel="noreferrer">research/papers/pdfs/2606.09483.pdf</a> (11 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Long-term memory for an LLM agent is more than retrieving the right passage at the right time. Current memory systems collapse belief revision, causal coupling, and cross-domain abstraction into a single retrieval surface tuned for surface recall, and consequently struggle on implicit personalisation that requires reasoning over how a user has evolved. We propose DCPM, which reorganises agent memory along a cognitive capability hierarchy ascending from raw inputs and atomic facts, through diachronic belief trajectories and identity, to domain schemas, latent intentions and cross-domain patterns. The hierarchy is driven by two processes inheriting the architectural split of dual-process theory: a synchronous daytime writer (System1) that records belief revisions as doubly linked supersedes chains, and an asynchronous nighttime engine (System2) that induces schemas and intentions and sweeps for cross-domain collisions abstracted into higher-level core schemas. On LongMemEval, PersonaMem and PersonaMem-v2, enabling System2 contributes most where the benchmark rewards implicit cross-session inference (up to +5.20 on PersonaMem-v2) and least on span recall, matching the architectural prediction.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 DCPM：將 agent memory 沿「認知能力階層」重組——從原始輸入/原子事實，經 diachronic belief trajectory 與 identity，到 domain schema、latent intention 與 cross-domain pattern。</li><li>借用 dual-process theory 的架構切分：同步白天 writer（System1）以 doubly linked supersedes chain 記錄 belief revision；非同步夜間引擎（System2）誘導 schema/intention 並掃描 cross-domain collision，抽象為更高層 core schema。</li><li>主張長期記憶不只是「正確時刻取出正確段落」，而需對「使用者如何演變」進行推理。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>於 LongMemEval、PersonaMem、PersonaMem-v2 評測：啟用 System2 在 benchmark 獎勵 implicit cross-session inference 時貢獻最大（PersonaMem-v2 上 up to +5.20），在 span recall 上貢獻最小，符合架構預測。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未列明確 limitation 章節；判斷弱點：僅 4 作者短篇（11 頁），System2 非同步引擎的計算/延遲成本未在 abstract 量化；增益集中於特定 benchmark 子任務，泛化性待驗證。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>System1/System2 分工對應 context-management 的「online vs offline consolidation」思路；非同步夜間 schema 誘導 ≈ memory-compactor 的離線壓縮+整合 gate 概念。</li><li>「belief revision 以 supersedes chain 記錄」呼應 core.md RECORD「checkpoint + 反思入庫」與 LESSONS.md 的演化迴圈——舊 belief 不刪、標記 superseded。</li><li>⚠️ 落地門檻：本庫 MEMORY/LESSONS 為人工/hook 維護的 markdown，非自動 cross-domain schema induction；DCPM 的「夜間引擎」屬域外研究系統，僅概念可借鑑。</li></ul>',16)])])}const u=a(s,[["render",n]]);export{g as __pageData,u as default};
